// SPDX-License-Identifier: ISC
//! Replay of dcrd's agenda-active mempool tests (M1-p#4), generated by
//! running dcrd's own mempool test harness (`newPoolHarness`) at the
//! parity pin through the steps of `TestRevocationsWithAutoRevocationsEnabled`,
//! `TestSubsidySplitSemantics` and `TestSubsidySplitR2Semantics`
//! (`internal/mempool/mempool_test.go:2984`, `:3226`, `:3330`) and
//! recording every chain mutation, pool call and resulting pool state
//! (`data/review_agenda_vectors.txt`).
//!
//! Mainnet runs with the automatic ticket revocations (DCP0009) and
//! both subsidy split (DCP0010, DCP0012) agendas active, and every
//! other pool replay answers all three agenda queries with `false`.
//! These sections pin what the pool does with them on:
//!
//! - `autorev`: a v2 revocation with a fee is rejected
//!   (`ErrRegTxCreateStakeOut`), a v1 one too
//!   (`ErrInvalidRevocationTxVersion`), a zero-fee v2 one is accepted,
//!   and the next stake prune drops it from the main pool.
//! - `ss` / `ssr2`: a vote paying the subsidy of the other side of the
//!   agenda is rejected (`ErrBadStakebaseAmountIn`) and the matching
//!   one accepted, with the agenda off and then on, so a swapped or
//!   dropped `SubsidySplitVariant` fails here.
//!
//! dcrd's stage pool holds only ticket purchases, so its revocation
//! prune branch (`pruneStakeTx`, `mempool.go:2071-2079`) has nothing
//! to reach, in dcrd's tests or here.

// Test-harness arithmetic over bounded lengths.
#![allow(clippy::arithmetic_side_effects)]

mod common;

use common::{chain_from_init, error_kind, harness_policy, hash_csv, parse_hash, parse_tx};
use dcroxide_chaincfg::mainnet_params;
use dcroxide_mempool::TxPool;
use dcroxide_testutil::unhex;
use dcroxide_wire::BlockHeader;

/// The row counts one section replays: process-transaction rows,
/// state checks, and agenda toggles.
#[derive(Debug, Default, PartialEq, Eq)]
struct Counts {
    pt: usize,
    state: usize,
    toggles: usize,
}

fn run_section(lines: &[&str]) -> Counts {
    let params = mainnet_params();
    let init: Vec<&str> = lines[0].split(' ').collect();
    let chain = chain_from_init(&init);
    let policy = harness_policy(params.coinbase_maturity);
    let mut pool = TxPool::new(chain, policy, &params);
    let mut counts = Counts::default();

    for line in &lines[1..] {
        let f: Vec<&str> = line.split(' ').collect();
        match f[0] {
            "autorev" => {
                pool.chain.auto_revocations_active = f[1] == "1";
                counts.toggles += 1;
            }
            "ss" => {
                pool.chain.subsidy_split_active = f[1] == "1";
                counts.toggles += 1;
            }
            "ssr2" => {
                pool.chain.subsidy_split_r2_active = f[1] == "1";
                counts.toggles += 1;
            }
            "sethgt" => {
                pool.chain.best_height = f[1].parse().expect("height");
            }
            "besthash" => {
                // besthash <hash> <headerhex>
                let hash = parse_hash(f[1]);
                let (header, _) = BlockHeader::from_bytes(&unhex(f[2])).expect("header");
                pool.chain.headers.insert(hash.0, header);
                pool.chain.best_hash = hash;
            }
            "utxo" => {
                let tx = parse_tx(f[1]);
                let height: i64 = f[2].parse().expect("height");
                let block_index: u32 = f[3].parse().expect("block index");
                pool.chain
                    .utxos
                    .add_tx_outs(&tx, height, block_index, false);
            }
            "pt" => {
                // pt <txhex> <alloworphan> <allowhighfees> <tag>
                //    (ok <acceptedcsv> | <kind> -)
                let tx = parse_tx(f[1]);
                let tag: u64 = f[4].parse().expect("tag");
                match pool.process_transaction(&tx, f[2] == "true", f[3] == "true", tag) {
                    Ok(accepted) => {
                        assert_eq!("ok", f[5], "{line}: unexpected acceptance");
                        assert_eq!(hash_csv(&accepted), f[6], "{line}: accepted list");
                    }
                    Err(err) => {
                        assert_eq!(error_kind(&err), f[5], "{line}: kind ({err:?})");
                    }
                }
                counts.pt += 1;
            }
            "rmtx" => {
                let tx = parse_tx(f[1]);
                pool.remove_transaction(&tx, &tx.tx_hash(), f[2] == "true");
            }
            "prune" => {
                pool.prune_stake_tx(f[1].parse().expect("sdiff"), f[2].parse().expect("height"));
            }
            "state" => {
                // state <count> <pool> <orphans> <staged> <tspends>
                assert_eq!(pool.count().to_string(), f[1], "{line}: count");
                assert_eq!(hash_csv(&pool.tx_hashes()), f[2], "{line}: pool");
                assert_eq!(hash_csv(&pool.orphan_hashes()), f[3], "{line}: orphans");
                assert_eq!(hash_csv(&pool.staged_hashes()), f[4], "{line}: staged");
                assert_eq!(hash_csv(&pool.tspend_hashes()), f[5], "{line}: tspends");
                counts.state += 1;
            }
            other => panic!("unknown row tag {other}"),
        }
    }
    counts
}

/// The rows of the named section, from its `init` row up to the next
/// section header.
fn section<'a>(lines: &[&'a str], name: &str) -> Vec<&'a str> {
    let header = format!("net {name}");
    let start = lines
        .iter()
        .position(|l| *l == header)
        .unwrap_or_else(|| panic!("section {name}"));
    lines[start + 1..]
        .iter()
        .take_while(|l| !l.starts_with("net "))
        .copied()
        .collect()
}

fn vectors() -> Vec<&'static str> {
    include_str!("data/review_agenda_vectors.txt")
        .lines()
        .collect()
}

/// dcrd `TestRevocationsWithAutoRevocationsEnabled`.
#[test]
fn revocations_follow_dcrd_with_auto_revocations_active() {
    let counts = run_section(&section(&vectors(), "autorev"));
    assert_eq!(
        counts,
        Counts {
            pt: 5,
            state: 6,
            toggles: 1
        }
    );
}

/// dcrd `TestSubsidySplitSemantics` (DCP0010).
#[test]
fn votes_follow_dcrd_across_the_subsidy_split_agenda() {
    let counts = run_section(&section(&vectors(), "ss"));
    assert_eq!(
        counts,
        Counts {
            pt: 4,
            state: 5,
            toggles: 4
        }
    );
}

/// dcrd `TestSubsidySplitR2Semantics` (DCP0012).
#[test]
fn votes_follow_dcrd_across_the_subsidy_split_r2_agenda() {
    let counts = run_section(&section(&vectors(), "ssr2"));
    assert_eq!(
        counts,
        Counts {
            pt: 4,
            state: 5,
            toggles: 4
        }
    );
}
